1	package posemap
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// Correct 提交一次已确认回环校正。
9	//
10	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
11	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
12	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
13	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
14	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
15	// 之后至该帧的原运动方差累计值。更早的位姿不变。
16	//
17	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
18	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
19	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
20	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
21	// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
22	// 时间、路标标识与出现编号，而不是误报为距离冲突。
23	//
24	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
25	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
26	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
27	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
28		m.mu.Lock()
29		defer m.mu.Unlock()
30		if m.closed {
31			return CorrectionRecord{}, ErrClosed
32		}
33		st := m.state
34	
35		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
36		// 不做任何校验或状态变更，即使其后又提交过其他校正。
37		if hash, ok := st.corrIndex[req.ID]; ok {
38			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
39				return cloneRecord(st.correctionRecordByID(req.ID)), nil
40			}
41			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
42		}
43	
44		if req.ID == "" {
45			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
46		}
47		tgt := req.Target
48		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
49			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
50		}
51		if tgt.Variance < 0 {
52			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
53		}
54	
55		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
56		anchorIdx := -1
57		for j := 1; j < len(st.trajectory); j++ {
58			if st.trajectory[j].Time == req.Anchor {
59				anchorIdx = j
60				break
61			}
62		}
63		if anchorIdx < 0 {
64			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
65		}
66		end := len(st.trajectory) - 1
67	
68		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
69		for k := anchorIdx - 1; k < len(st.sources); k++ {
70			if st.sources[k] == nil {
71				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
72			}
73		}
74	
75		oldAnchor := st.trajectory[anchorIdx]
76		newHeading := normalizeAngle(tgt.Heading)
77		// 相对位姿整体旋转 δ；平移锚点到目标位置。
78		dHeading := normalizeAngle(newHeading - oldAnchor.Heading)
79		cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
80	
81		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
82		next := append([]Pose(nil), st.trajectory...)
83		accumVar := tgt.Variance
84		for j := anchorIdx; j <= end; j++ {
85			old := st.trajectory[j]
86			if j > anchorIdx {
87				accumVar += st.sources[j-1].moveVariance
88			}
89			dx := old.X - oldAnchor.X
90			dy := old.Y - oldAnchor.Y
91			np := Pose{
92				Time:     old.Time,
93				X:        tgt.X + cosD*dx - sinD*dy,
94				Y:        tgt.Y + sinD*dx + cosD*dy,
95				Heading:  normalizeAngle(old.Heading + dHeading),
96				Variance: accumVar,
97			}
98			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
99				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
100			}
101			next[j] = np
102		}
103	
104		// occKey 标识某一路标的某一次出现。回环校正跨越同一路标的多次出现
105		// 时，各次出现分别聚合、分别遵守合并距离限制。观测按所在帧时间归入
106		// 当时的那次出现，时间边界规则与打开文件时的归属校验共享（见
107		// occurrence.go）；已接受观测必然属于某次出现。
108		type occKey struct {
109			id  string
110			num int
111		}
112	
113		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
114		affected := make(map[occKey]struct{})
115		for j := anchorIdx; j <= end; j++ {
116			t := st.trajectory[j].Time
117			for _, ob := range st.sources[j-1].observations {
118				affected[occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}] = struct{}{}
119			}
120		}
121		affectedKeys := make([]occKey, 0, len(affected))
122		for k := range affected {
123			affectedKeys = append(affectedKeys, k)
124		}
125		sort.Slice(affectedKeys, func(i, j int) bool {
126			if affectedKeys[i].id != affectedKeys[j].id {
127				return affectedKeys[i].id < affectedKeys[j].id
128			}
129			return affectedKeys[i].num < affectedKeys[j].num
130		})
131	
132		// 逐“出现”运行聚合：旧文件第 1 次出现的既有观测作为固定“旧贡献”
133		// 起点（位置不随校正改变），其余观测按帧时间与同帧输入次序、以当前/
134		// 校正后位姿重放，接纳与合并规则（转换、非有限优先、首条建点、距离
135		// 判定、增量平均、计数）与导入共享同一实现（见 aggregate.go）。同一路
136		// 标的不同出现互不参与彼此的合并。
137		aggs := make(map[occKey]*observationAgg, len(affectedKeys))
138		for _, k := range affectedKeys {
139			occ := st.landmarks[k.id].appearances[k.num-1]
140			a := &observationAgg{}
141			if occ.legacyCount > 0 {
142				// 旧文件第 1 次出现：固定旧贡献作为聚合起点，不随后续校正改变。
143				a.seed(occ.legacyCount, occ.legacyMX, occ.legacyMY)
144			}
145			aggs[k] = a
146		}
147		for j := 1; j <= end; j++ {
148			src := st.sources[j-1]
149			if src == nil {
150				continue // 旧文件帧：观测已计入对应出现的 legacy 起点
151			}
152			pose := next[j]
153			t := st.trajectory[j].Time
154			for _, ob := range src.observations {
155				k := occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}
156				a, ok := aggs[k]
157				if !ok {
158					continue
159				}
160				// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
161				// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
162				// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
163				// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
164				// 观测、记录仍有效还是已失效。
165				switch a.admit(pose, ob, st.config.MergeDistance) {
166				case obsNonFinite:
167					return CorrectionRecord{}, &RejectError{
168						Kind:          RejectNonFinite,
169						Time:          st.trajectory[j].Time,
170						HasTime:       true,
171						Landmark:      ob.ID,
172						HasLandmark:   true,
173						Occurrence:    k.num,
174						HasOccurrence: true,
175					}
176				case obsConflict:
177					return CorrectionRecord{}, &RejectError{
178						Kind:          RejectLandmarkConflict,
179						Time:          st.trajectory[j].Time,
180						HasTime:       true,
181						Landmark:      ob.ID,
182						HasLandmark:   true,
183						Occurrence:    k.num,
184						HasOccurrence: true,
185					}
186				}
187			}
188		}
189		for _, k := range affectedKeys {
190			a := aggs[k]
191			occ := st.landmarks[k.id].appearances[k.num-1]
192			if !isFinite(a.x) || !isFinite(a.y) {
193				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
194			}
195			if a.count != occ.count {
196				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
197				return CorrectionRecord{}, ErrCorrupt
198			}
199		}
200	
201		// ---- 组装校正前后快照（记录不可变） ----
202		rec := &CorrectionRecord{
203			ID:        req.ID,
204			Anchor:    req.Anchor,
205			Target:    tgt,
206			EndTime:   st.trajectory[end].Time,
207			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
208			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
209		}
210		for j := anchorIdx; j <= end; j++ {
211			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
212		}
213		for _, k := range affectedKeys {
214			occ := st.landmarks[k.id].appearances[k.num-1]
215			a := aggs[k]
216			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
217				ID:         k.id,
218				Occurrence: k.num,
219				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
220				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
221			})
222		}
223	
224		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
225		oldTraj := append([]Pose(nil), st.trajectory...)
226		type occSnapshot struct {
227			key  occKey
228			occ  *occurrenceState
229			x, y float64
230		}
231		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
232		for _, k := range affectedKeys {
233			occ := st.landmarks[k.id].appearances[k.num-1]
234			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
235		}
236		oldCorrLen := len(st.corrections)
237	
238		st.trajectory = next
239		for _, s := range oldOcc {
240			a := aggs[s.key]
241			s.occ.x, s.occ.y = a.x, a.y
242		}
243		st.corrections = append(st.corrections, rec)
244		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
245	
246		if err := m.saveReplace(); err != nil {
247			st.trajectory = oldTraj
248			for _, s := range oldOcc {
249				s.occ.x, s.occ.y = s.x, s.y
250			}
251			st.corrections = st.corrections[:oldCorrLen]
252			delete(st.corrIndex, req.ID)
253			return CorrectionRecord{}, err
254		}
255		return cloneRecord(rec), nil
256	}
257	
258	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
259	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
260	func (m *Map) Corrections() ([]CorrectionRecord, error) {
261		m.mu.Lock()
262		defer m.mu.Unlock()
263		if m.closed {
264			return nil, ErrClosed
265		}
266		out := make([]CorrectionRecord, 0, len(m.state.corrections))
267		for _, rec := range m.state.corrections {
268			out = append(out, cloneRecord(rec))
269		}
270		return out, nil
271	}
272	
273	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
274		for _, rec := range st.corrections {
275			if rec.ID == id {
276				return rec
277			}
278		}
279		return nil
280	}
281	
282	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
283		if rec == nil {
284			return CorrectionRecord{}
285		}
286		cp := *rec
287		cp.Poses = append([]PoseChange(nil), rec.Poses...)
288		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
289		return cp
290	}
